CREATE DATABASE IF NOT EXISTS oracle_corpus;
USE oracle_corpus;
CREATE TABLE IF NOT EXISTS skew_fact (f_id BIGINT NOT NULL, f_key INT NOT NULL, f_val INT NOT NULL) ENGINE=OLAP DUPLICATE KEY (f_id) DISTRIBUTED BY HASH(f_id) BUCKETS 8 PROPERTIES ('replication_num'='1');
CREATE TABLE IF NOT EXISTS skew_dim (d_key INT NOT NULL, d_attr INT NOT NULL, d_name VARCHAR(16) NOT NULL) ENGINE=OLAP DUPLICATE KEY (d_key) DISTRIBUTED BY HASH(d_key) BUCKETS 4 PROPERTIES ('replication_num'='1');
CREATE TABLE IF NOT EXISTS fan_left (l_id BIGINT NOT NULL, l_key INT NOT NULL, l_grp INT NOT NULL, l_val INT NOT NULL) ENGINE=OLAP DUPLICATE KEY (l_id) DISTRIBUTED BY HASH(l_id) BUCKETS 8 PROPERTIES ('replication_num'='1');
CREATE TABLE IF NOT EXISTS fan_right (r_id BIGINT NOT NULL, r_key INT NOT NULL, r_val INT NOT NULL) ENGINE=OLAP DUPLICATE KEY (r_id) DISTRIBUTED BY HASH(r_id) BUCKETS 2 PROPERTIES ('replication_num'='1');
CREATE TABLE IF NOT EXISTS wide_dim (w_id BIGINT NOT NULL, w_tag INT NOT NULL, w_payload VARCHAR(512) NOT NULL) ENGINE=OLAP DUPLICATE KEY (w_id) DISTRIBUTED BY HASH(w_id) BUCKETS 4 PROPERTIES ('replication_num'='1');
CREATE TABLE IF NOT EXISTS hc_fact (h_id BIGINT NOT NULL, h_user BIGINT NOT NULL, h_val INT NOT NULL) ENGINE=OLAP DUPLICATE KEY (h_id) DISTRIBUTED BY HASH(h_id) BUCKETS 8 PROPERTIES ('replication_num'='1');
INSERT INTO skew_fact SELECT g, CASE WHEN g % 20 = 0 THEN CAST(g % 100000 + 2 AS INT) ELSE 1 END, CAST(g % 1000 AS INT) FROM (SELECT CAST(generate_series AS BIGINT) AS g FROM TABLE(generate_series(1, 8000000))) x;
INSERT INTO skew_dim SELECT CAST(g AS INT), CAST(g % 50 AS INT), concat('dim_', CAST(g AS VARCHAR)) FROM (SELECT CAST(generate_series AS BIGINT) AS g FROM TABLE(generate_series(1, 100001))) x;
INSERT INTO fan_left SELECT g, CAST(g % 1000 AS INT), CAST(g % 97 AS INT), CAST(g % 100 AS INT) FROM (SELECT CAST(generate_series AS BIGINT) AS g FROM TABLE(generate_series(1, 1000000))) x;
INSERT INTO fan_right SELECT g, CAST(g % 1000 AS INT), CAST(g % 10 AS INT) FROM (SELECT CAST(generate_series AS BIGINT) AS g FROM TABLE(generate_series(1, 20000))) x;
INSERT INTO wide_dim SELECT g, CAST(g % 100 AS INT), concat(md5(CAST(g AS VARCHAR)), md5(CAST(g * 3 AS VARCHAR)), md5(CAST(g * 7 AS VARCHAR)), md5(CAST(g * 11 AS VARCHAR)), md5(CAST(g * 13 AS VARCHAR)), md5(CAST(g * 17 AS VARCHAR))) FROM (SELECT CAST(generate_series AS BIGINT) AS g FROM TABLE(generate_series(1, 1000000))) x;
INSERT INTO hc_fact SELECT g, (g * 7919) % 3000017, CAST(g % 1000 AS INT) FROM (SELECT CAST(generate_series AS BIGINT) AS g FROM TABLE(generate_series(1, 3000000))) x;
ANALYZE FULL TABLE skew_fact WITH SYNC MODE;
ANALYZE FULL TABLE skew_dim WITH SYNC MODE;
ANALYZE FULL TABLE fan_left WITH SYNC MODE;
ANALYZE FULL TABLE fan_right WITH SYNC MODE;
ANALYZE FULL TABLE wide_dim WITH SYNC MODE;
ANALYZE FULL TABLE hc_fact WITH SYNC MODE;
SELECT 'skew_fact', COUNT(*) FROM skew_fact UNION ALL SELECT 'skew_dim', COUNT(*) FROM skew_dim UNION ALL SELECT 'fan_left', COUNT(*) FROM fan_left UNION ALL SELECT 'fan_right', COUNT(*) FROM fan_right UNION ALL SELECT 'wide_dim', COUNT(*) FROM wide_dim UNION ALL SELECT 'hc_fact', COUNT(*) FROM hc_fact;
